{
  "version": 1,
  "defaultSuite": "smoke",
  "suites": {
    "smoke": [
      { "action": "wait", "ms": 2500 },
      {
        "action": "assert",
        "expr": "!!document.querySelector('input')",
        "matcher": "truthy",
        "note": "搜索框在（这个应用以搜索为主页）"
      },
      {
        "action": "eval",
        "expr": "(() => { const i = document.querySelector('input'); const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set; setter.call(i, 'blender open movie'); i.dispatchEvent(new Event('input', { bubbles: true })); const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === '搜索'); if (!b) throw new Error('搜索按钮未找到'); b.click(); return 'ok' })()",
        "note": "受控 input 必须用原生 setter 再派发 input 事件，直接改 .value 不触发 React 的 onChange"
      },
      { "action": "wait", "ms": 5000 },
      { "action": "wait", "ms": 4000, "note": "单步 wait 上限 5000ms，长等待要拆成多段" },
      {
        "action": "assert",
        "expr": "!/搜索失败|联网权限/.test(document.body.innerText)",
        "matcher": "truthy",
        "note": "InnerTube 通了。注意响应有 450KB+，默认 200KB 上限会静默截断成解不出的半截 JSON"
      },
      {
        "action": "assert",
        "expr": "document.querySelectorAll('[data-row-id]').length >= 3",
        "matcher": "truthy",
        "note": "出结果（虚拟列表只渲可见区，故不检查全量条数）"
      },
      {
        "action": "assert",
        "expr": "[...document.querySelectorAll('img')].some(i => i.src.startsWith('applet://localhost/image/'))",
        "matcher": "truthy",
        "note": "缩略图走 applet://image/ —— 裸 https 会被 CSP 静默拦成空白，这是唯一能自动逮到的地方"
      },
      {
        "action": "eval",
        "expr": "(() => { const r = document.querySelector('[data-row-id]'); if (!r) throw new Error('无结果行'); r.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 5000 },
      { "action": "wait", "ms": 5000 },
      { "action": "wait", "ms": 4000, "note": "解析要走宿主 extractor + 网络握手，给足时间" },
      {
        "action": "assert",
        "expr": "/清晰度|解析不了|没有可播放/.test(document.body.innerText)",
        "matcher": "truthy",
        "note": "播放页有明确结论：要么列出清晰度，要么说清为什么播不了 —— 不允许停在空白"
      }
    ]
  }
}

// YouTube（com.aibox.youtube）—— 搜索、播放，走宿主的解析栈与原生播放器。
//
// ## 这个应用刻意**不做**的事：自己解析取流
//
// YouTube 的取流是持续对抗（客户端选型、visitorData 握手、格式下线），且 >360p 全是
// 音视频分离的 DASH —— WebView 里放不了，纯 JS 也拼不出来。
// 所以播放地址一律经 `aibox.video.resolve` 由宿主给，页面只负责「选哪个清晰度」。
//
// 直接后果是：这个应用能播 1080p60，而一个自己解析的版本只能到 360p。

import React from 'react'
import { useSubpageStack } from 'aibox/ui'
import SearchPage from './components/SearchPage.jsx'
import PlayerPage from './components/PlayerPage.jsx'
import { THEME_CSS, C } from './components/theme.js'
import { registerActions } from './lib/actions.js'

// 对外提供的 2 个 AI 动作。**模块求值期就注册**：无头执行时页面不挂载任何组件，
// 等 React 副作用就来不及了。
registerActions()

function useTheme() {
  React.useEffect(() => {
    if (!document.getElementById('__yt_css__')) {
      const style = document.createElement('style')
      style.id = '__yt_css__'
      style.textContent = THEME_CSS
      document.head.appendChild(style)
    }
    const query = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null
    const apply = () => {
      document.documentElement.setAttribute(
        'data-prefers-color-scheme', query && query.matches ? 'dark' : 'light')
    }
    apply()
    query?.addEventListener?.('change', apply)
    return () => query?.removeEventListener?.('change', apply)
  }, [])
}

export default function App() {
  useTheme()
  // 播放页走原生页栈：推入动画、边缘返回手势由宿主给。
  const stack = useSubpageStack({
    pathFor: (route) => `#/watch/${route.video.id}`,
    titleFor: (route) => route.video.title || '视频',
  })

  const open = React.useCallback((video) => {
    stack.push({ video })
  }, [stack])

  return (
    <div style={{
      height: '100vh', display: 'flex', flexDirection: 'column',
      background: C.bg, color: C.text, overflow: 'hidden',
    }}>
      <div style={{ flex: 1, minHeight: 0 }}>
        {stack.route
          ? <PlayerPage video={stack.route.video} onOpen={open} />
          : <SearchPage onOpen={open} />}
      </div>
    </div>
  )
}

// 播放页：解析 → 选清晰度 → 交给宿主播放器。
//
// ## 这一页的核心是「只列能播的」
//
// `resolve` 回来的每条格式带一个 `playable`。它为假的原因是**这个构建里没编入分离流合成后端**——
// YouTube 的高清全是 dash（音视频两条 URL），没有那个后端就播不了。
//
// 所以这里**过滤掉不可播的**，而不是列出来让用户点了黑屏。同时，如果过滤后一条都不剩，
// 明确告诉用户原因，而不是显示一个空列表。

import React from 'react'
import { EmptyState, PrimaryButton, Spinner } from './primitives.jsx'
import VideoCard from './VideoCard.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import * as innertube from '../lib/innertube.js'
import {
  capabilities, copyText, haptic, imageURL, loadPref, onVideoProgress,
  openInBrowser, play, resolve, savePref, share, toast,
} from '../lib/host.js'
import { formatDuration, qualityLabel } from '../lib/format.js'

const PROGRESS_KEY = 'watch-progress'
const HISTORY_KEY = 'watch-history'

export default function PlayerPage({ video, onOpen }) {
  const [state, setState] = React.useState('resolving')   // resolving | ready | error
  const [media, setMedia] = React.useState(null)
  const [error, setError] = React.useState('')
  const [caps, setCaps] = React.useState({ available: true, resolve: true, dash: true })
  const [busy, setBusy] = React.useState(false)
  const [progress, setProgress] = React.useState(null)
  const [related, setRelated] = React.useState([])
  const pending = React.useRef(null)

  React.useEffect(() => {
    let alive = true
    setState('resolving')
    capabilities().then((c) => { if (alive) setCaps(c) })
    resolve(video.url)
      .then((r) => {
        if (!alive) return
        setMedia(r)
        setState('ready')
        // 写进历史。读-改-写要合并，不能整表覆盖。
        loadPref(HISTORY_KEY, []).then((list) => {
          const rest = (list || []).filter((x) => x.id !== video.id)
          savePref(HISTORY_KEY, [{ ...video, at: Date.now() }, ...rest].slice(0, 50))
        }).catch(() => {})
      })
      .catch((err) => {
        if (!alive) return
        setError(String(err?.message || err))
        setState('error')
      })
    // 「相关」用标题里的关键词再搜一次——InnerTube 的 related 需要额外 token，
    // 用搜索近似是诚实且够用的做法（列表里明说是「相似视频」而不是「相关推荐」）。
    const keyword = String(video.title || '').split(/[|｜\-–—[\]【】]/)[0].trim().slice(0, 20)
    if (keyword) {
      innertube.search(keyword).then((list) => {
        if (alive) setRelated(list.filter((v) => v.id !== video.id).slice(0, 12))
      }).catch(() => {})
    }
    return () => { alive = false }
  }, [video.id, video.url])

  React.useEffect(() => {
    let lastWhole = -1
    const off = onVideoProgress((snapshot) => {
      if (!snapshot?.mine) return
      if (snapshot.currentTime > 5 && snapshot.duration > 0) {
        const ratio = snapshot.currentTime / snapshot.duration
        pending.current = { key: video.id, value: ratio > 0.95 ? 0 : Math.floor(snapshot.currentTime) }
      }
      // 按整秒去重：事件是 2Hz，而这一页下面挂着十几条相似视频，每秒重渲两次全是白烧
      // （播放时用户其实在原生全屏播放器里）。
      const whole = Math.floor(snapshot.currentTime)
      if (whole === lastWhole) return
      lastWhole = whole
      setProgress(snapshot)
    })
    return off
  }, [video.id])

  React.useEffect(() => () => {
    const p = pending.current
    if (!p) return
    loadPref(PROGRESS_KEY, {})
      .then((all) => savePref(PROGRESS_KEY, { ...(all || {}), [p.key]: p.value }))
      .catch(() => {})
  }, [])

  const playable = React.useMemo(
    () => (media?.formats || []).filter((f) => f.playable), [media])

  const start = React.useCallback(async (formatID) => {
    if (busy) return
    setBusy(true)
    haptic('medium')
    try {
      const saved = await loadPref(PROGRESS_KEY, {})
      await play({
        sourceURL: video.url,
        formatID,
        resumeFrom: Number(saved?.[video.id]) || 0,
      })
    } catch (err) {
      toast(`播放失败：${err?.message || err}`)
    } finally {
      setBusy(false)
    }
  }, [busy, video.url, video.id])

  if (state === 'resolving') return <Spinner label="解析中" />

  if (state === 'error') {
    return (
      <EmptyState
        title="解析不了这个视频"
        detail={caps.resolve
          ? error
          : '这个版本没有编入媒体解析能力，播放不了 YouTube 视频。'}
        actionLabel="用浏览器打开"
        onAction={() => openInBrowser(video.url)}
      />
    )
  }

  return (
    <div className="yt-scroll" style={{ height: '100%', overflowY: 'auto', background: C.bg }}>
      <div
        onClick={() => playable.length && start(playable[0].id)}
        style={{
          position: 'relative', width: '100%', aspectRatio: '16 / 9',
          background: C.surface, overflow: 'hidden',
        }}
      >
        {video.cover ? (
          <img src={imageURL(video.cover, 400)} alt=""
            style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
        ) : null}
        <div style={{
          position: 'absolute', inset: 0, display: 'flex',
          alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.25)',
        }}>
          <div style={{
            width: 58, height: 58, borderRadius: 29, background: 'rgba(0,0,0,0.55)',
            color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 24,
          }}>
            {busy ? '···' : '▶'}
          </div>
        </div>
        {progress?.mine && progress.duration > 0 ? (
          <div style={{
            position: 'absolute', left: 0, bottom: 0, height: 3,
            width: `${Math.min(100, (progress.currentTime / progress.duration) * 100)}%`,
            background: C.brand,
          }} />
        ) : null}
      </div>

      <div style={{ padding: SPACE.s4 }}>
        <div style={{ fontSize: 17, fontWeight: 600, color: C.text, lineHeight: 1.4 }}>
          {media?.title || video.title}
        </div>
        <div style={{ fontSize: 12, color: C.faint, marginTop: SPACE.s2 }}>
          {[media?.uploader || video.author, video.viewLabel, video.published].filter(Boolean).join(' · ')}
        </div>

        {/* 清晰度：只列能播的 */}
        {playable.length ? (
          <div style={{ marginTop: SPACE.s4 }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: C.sub, marginBottom: SPACE.s2 }}>
              清晰度
            </div>
            <div className="yt-scroll" style={{ display: 'flex', gap: SPACE.s2, overflowX: 'auto' }}>
              {playable.map((f) => (
                <button
                  key={f.id}
                  type="button"
                  onClick={() => start(f.id)}
                  disabled={busy}
                  style={{
                    flexShrink: 0, border: 'none', borderRadius: RADIUS.lg,
                    padding: `6px ${SPACE.s3}px`, fontSize: 13, lineHeight: 1.3,
                    background: C.surface, color: C.text, textAlign: 'left',
                  }}
                >
                  <div>{qualityLabel(f.width, f.height, f.quality)}</div>
                  {f.width && f.height ? (
                    <div style={{ fontSize: 10, color: C.faint, fontVariantNumeric: 'tabular-nums' }}>
                      {f.width}×{f.height}
                    </div>
                  ) : null}
                </button>
              ))}
            </div>
          </div>
        ) : (
          <div style={{
            marginTop: SPACE.s4, padding: SPACE.s3, borderRadius: RADIUS.md,
            background: C.brandDim, fontSize: 13, color: C.sub, lineHeight: 1.6,
          }}>
            {caps.dash
              ? '这个视频没有可播放的清晰度。'
              : '这个视频只提供分离流（音视频分开），而当前版本没有编入合流能力，所以播不了。'}
          </div>
        )}

        <div style={{ display: 'flex', gap: SPACE.s2, marginTop: SPACE.s4 }}>
          <PrimaryButton onClick={() => playable.length && start(playable[0].id)}
            disabled={busy || !playable.length}>
            {busy ? '正在准备…' : '播放'}
          </PrimaryButton>
          <button
            type="button"
            onClick={async () => { await copyText(video.url); toast('链接已复制') }}
            style={{
              border: `1px solid ${C.line}`, background: 'transparent', color: C.sub,
              borderRadius: RADIUS.md, padding: `0 ${SPACE.s4}px`, fontSize: 14, flexShrink: 0,
            }}
          >
            复制
          </button>
          <button
            type="button"
            onClick={() => share(video.title, video.url)}
            style={{
              border: `1px solid ${C.line}`, background: 'transparent', color: C.sub,
              borderRadius: RADIUS.md, padding: `0 ${SPACE.s4}px`, fontSize: 14, flexShrink: 0,
            }}
          >
            分享
          </button>
        </div>

        {media?.durationSeconds ? (
          <div style={{ fontSize: 12, color: C.faint, marginTop: SPACE.s3 }}>
            时长 {formatDuration(media.durationSeconds)} · 解析器 {media.extractor}
          </div>
        ) : null}
      </div>

      {related.length ? (
        <div style={{ borderTop: `8px solid ${C.surface}`, paddingTop: SPACE.s2 }}>
          <div style={{ padding: `${SPACE.s2}px ${SPACE.s4}px`, fontSize: 13, fontWeight: 600, color: C.sub }}>
            相似视频
          </div>
          {related.map((v) => (
            <VideoCard key={v.id} video={v} onOpen={onOpen} />
          ))}
        </div>
      ) : null}
      <div style={{ height: SPACE.s6 }} />
    </div>
  )
}

// 通用小件。刻意不引 antd-mobile 的重组件：这些都只有几十行，
// 自己写能精确控制高度（虚拟列表要求行高可预测）与配色（跟随系统深浅色）。

import React from 'react'
import { C, RADIUS, SPACE } from './theme.js'

/** 分段控件（首页的推荐/热门/排行）。 */
export function Segmented({ items, value, onChange }) {
  return (
    <div style={{
      display: 'flex',
      gap: SPACE.s2,
      padding: `${SPACE.s2}px ${SPACE.s4}px`,
      overflowX: 'auto',
      background: C.bg,
    }}>
      {items.map((item) => {
        const active = item.id === value
        return (
          <button
            key={item.id}
            type="button"
            onClick={() => onChange(item.id)}
            style={{
              flexShrink: 0,
              border: 'none',
              padding: `6px ${SPACE.s3}px`,
              borderRadius: RADIUS.lg,
              fontSize: 13,
              fontWeight: active ? 600 : 400,
              background: active ? C.brand : C.surface,
              color: active ? '#fff' : C.sub,
            }}
          >
            {item.label}
          </button>
        )
      })}
    </div>
  )
}

export function Spinner({ label = '加载中' }) {
  return (
    <div style={{ padding: SPACE.s6, textAlign: 'center', color: C.faint, fontSize: 13 }}>
      {label}…
    </div>
  )
}

/**
 * 空态。**必须区分「没有内容」和「出错了」**——两者混为一谈时，用户看到「暂无内容」
 * 而实际是网络挂了，会以为是 B 站没数据。
 */
export function EmptyState({ title, detail, actionLabel, onAction }) {
  return (
    <div style={{ padding: `${SPACE.s6}px ${SPACE.s5}px`, textAlign: 'center' }}>
      <div style={{ fontSize: 15, color: C.text, marginBottom: SPACE.s2 }}>{title}</div>
      {detail ? (
        <div style={{ fontSize: 13, color: C.faint, lineHeight: 1.5, marginBottom: SPACE.s4 }}>{detail}</div>
      ) : null}
      {actionLabel ? (
        <button
          type="button"
          onClick={onAction}
          style={{
            border: 'none', padding: `8px ${SPACE.s5}px`, borderRadius: RADIUS.lg,
            background: C.brand, color: '#fff', fontSize: 14,
          }}
        >
          {actionLabel}
        </button>
      ) : null}
    </div>
  )
}

/** 主按钮。 */
export function PrimaryButton({ children, onClick, disabled, block = true }) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      style={{
        display: block ? 'block' : 'inline-block',
        width: block ? '100%' : undefined,
        border: 'none',
        padding: `11px ${SPACE.s5}px`,
        borderRadius: RADIUS.md,
        background: disabled ? C.surface : C.brand,
        color: disabled ? C.faint : '#fff',
        fontSize: 15,
        fontWeight: 500,
      }}
    >
      {children}
    </button>
  )
}

/** 统计数字块（详情页的点赞/投币/收藏）。 */
export function StatItem({ label, value }) {
  return (
    <div style={{ flex: 1, textAlign: 'center' }}>
      <div style={{ fontSize: 15, color: C.text, fontVariantNumeric: 'tabular-nums' }}>{value}</div>
      <div style={{ fontSize: 11, color: C.faint, marginTop: 2 }}>{label}</div>
    </div>
  )
}

// 搜索页 —— 这个应用的主页。
//
// 为什么以搜索为主页而不是「首页推荐」：InnerTube 的首页/热门（`FEwhat_to_watch` / `FEtrending`）
// 实测要么 400、要么回一份没有视频条目的空壳，那需要登录态。与其做一个永远空着的推荐页，
// 不如把搜索放在正中，再用「最近观看」补上回访路径。

import React from 'react'
import { VirtualList, useKeyboardInset, useListGestures } from 'aibox/ui'
import VideoCard, { CARD_HEIGHT } from './VideoCard.jsx'
import { EmptyState, Spinner } from './primitives.jsx'
import { C, RADIUS, SPACE } from './theme.js'
import * as innertube from '../lib/innertube.js'
import { copyText, haptic, loadPref, openInBrowser, savePref, share, toast } from '../lib/host.js'

const RECENT_KEY = 'recent-queries'
const HISTORY_KEY = 'watch-history'

const ROW_ACTIONS = [
  { id: 'share', title: '分享', icon: 'square.and.arrow.up' },
  { id: 'copy', title: '复制链接', icon: 'link' },
  { id: 'web', title: '用浏览器打开', icon: 'safari' },
]

export default function SearchPage({ onOpen }) {
  const [keyword, setKeyword] = React.useState('')
  const [items, setItems] = React.useState([])
  const [state, setState] = React.useState('idle')   // idle | loading | ready | error
  const [error, setError] = React.useState('')
  const [needsPermission, setNeedsPermission] = React.useState(false)
  const [recent, setRecent] = React.useState([])
  const [history, setHistory] = React.useState([])
  const keyboard = useKeyboardInset()

  React.useEffect(() => {
    loadPref(RECENT_KEY, []).then((r) => setRecent(r || []))
    loadPref(HISTORY_KEY, []).then((h) => setHistory(h || []))
  }, [])

  const run = React.useCallback(async (text) => {
    const query = String(text || '').trim()
    if (!query) return
    setState('loading')
    setError('')
    setNeedsPermission(false)
    try {
      const list = await innertube.search(query)
      setItems(list)
      setState('ready')
      loadPref(RECENT_KEY, []).then((prev) => {
        const next = [query, ...(prev || []).filter((q) => q !== query)].slice(0, 10)
        setRecent(next)
        savePref(RECENT_KEY, next)
      }).catch(() => {})
    } catch (err) {
      setNeedsPermission(!!err?.permission)
      setError(String(err?.message || err))
      setState('error')
    }
  }, [])

  const handleAction = React.useCallback(async ({ rowId, actionId }) => {
    const video = items.find((v) => v.id === rowId) || history.find((v) => v.id === rowId)
    if (!video) return
    haptic('light')
    if (actionId === 'share') await share(video.title, video.url)
    else if (actionId === 'copy') { await copyText(video.url); toast('链接已复制') }
    else if (actionId === 'web') await openInBrowser(video.url)
  }, [items, history])

  const gestures = useListGestures('yt-results', { contextMenu: ROW_ACTIONS, onAction: handleAction })

  const bar = (
    <div style={{ padding: SPACE.s3, background: C.bg, display: 'flex', gap: SPACE.s2 }}>
      <input
        value={keyword}
        onChange={(e) => setKeyword(e.target.value)}
        onKeyDown={(e) => { if (e.key === 'Enter') { e.target.blur(); run(keyword) } }}
        placeholder="搜索 YouTube"
        enterKeyHint="search"
        style={{
          flex: 1, border: 'none', outline: 'none',
          padding: `9px ${SPACE.s3}px`, borderRadius: RADIUS.md,
          background: C.surface, color: C.text, fontSize: 14,
        }}
      />
      <button
        type="button"
        onClick={() => run(keyword)}
        style={{
          border: 'none', padding: `0 ${SPACE.s4}px`, borderRadius: RADIUS.md,
          background: C.brand, color: '#fff', fontSize: 14,
        }}
      >
        搜索
      </button>
    </div>
  )

  function Chips({ title, values, onPick }) {
    if (!values.length) return null
    return (
      <div style={{ padding: `0 ${SPACE.s4}px ${SPACE.s4}px` }}>
        <div style={{ fontSize: 13, color: C.sub, marginBottom: SPACE.s2 }}>{title}</div>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: SPACE.s2 }}>
          {values.map((v) => (
            <button
              key={v}
              type="button"
              onClick={() => onPick(v)}
              style={{
                border: 'none', padding: `7px ${SPACE.s3}px`, borderRadius: RADIUS.lg,
                background: C.surface, color: C.text, fontSize: 13,
              }}
            >
              {v}
            </button>
          ))}
        </div>
      </div>
    )
  }

  let body = null
  if (state === 'loading') body = <Spinner label="搜索中" />
  else if (state === 'error') {
    body = (
      <EmptyState
        title={needsPermission ? '还没有联网权限' : '搜索失败'}
        detail={error}
        actionLabel={needsPermission ? '我已开启，重新搜索' : '重试'}
        onAction={() => run(keyword)}
      />
    )
  } else if (state === 'ready' && items.length === 0) {
    body = <EmptyState title="没有找到相关视频" detail="换个关键词试试" />
  } else if (state === 'idle') {
    body = (
      <div style={{ paddingTop: SPACE.s2 }}>
        <Chips title="最近搜索" values={recent} onPick={(q) => { setKeyword(q); run(q) }} />
        {history.length ? (
          <div>
            <div style={{ padding: `0 ${SPACE.s4}px ${SPACE.s2}px`, fontSize: 13, color: C.sub }}>
              最近观看
            </div>
            {history.slice(0, 12).map((v) => (
              <VideoCard key={v.id} video={v} onOpen={onOpen} />
            ))}
          </div>
        ) : null}
        {!recent.length && !history.length ? (
          <EmptyState title="搜点什么吧" detail="YouTube 的首页需要登录，所以这里以搜索为主。" />
        ) : null}
      </div>
    )
  }

  return (
    <div style={{
      height: '100%', display: 'flex', flexDirection: 'column', background: C.bg,
      paddingBottom: keyboard.height,
      transition: `padding-bottom ${keyboard.animationMs}ms`,
    }}>
      {bar}
      {body ? (
        <div className="yt-scroll" style={{ flex: 1, overflowY: 'auto' }}>{body}</div>
      ) : (
        <VirtualList
          className="yt-scroll"
          style={{ flex: 1 }}
          regionId="yt-results"
          items={items}
          keyExtractor={(v) => v.id}
          estimatedRowHeight={CARD_HEIGHT}
          restoreKey="yt-results"
          footer={<div style={{ height: SPACE.s6 }} />}
          onVisibleRowsChange={gestures.onVisibleRowsChange}
          renderRow={(video) => <VideoCard video={video} onOpen={onOpen} />}
        />
      )}
    </div>
  )
}

